"""Align producer fixture with native YAML scene ceiling, preserving actor requests."""
import argparse,hashlib,json,shutil
from pathlib import Path


def build(source,out):
    from pxr import Usd
    source=Path(source).resolve();out=Path(out).resolve();out.mkdir(parents=True,exist_ok=False);shutil.copy2(source/'probe.usda',out/'probe.usda');probe=Usd.Stage.Open(str(out/'probe.usda'),load=Usd.Stage.LoadNone);p=probe.GetPrimAtPath('/World/PhysicsScene');before={a.GetName():str(a.Get()) for a in p.GetAttributes()};assert p.GetAttribute('physxScene:minPositionIterationCount').Get()==64 and p.GetAttribute('physxScene:maxPositionIterationCount').Get()==64;p.GetAttribute('physxScene:maxPositionIterationCount').Set(128);after={a.GetName():str(a.Get()) for a in p.GetAttributes()};assert [k for k in before if before[k]!=after[k]]==['physxScene:maxPositionIterationCount'];probe.GetRootLayer().Save();scene=Usd.Stage.CreateNew(str(out/'scene.usda'));scene.GetRootLayer().subLayerPaths=[str(source/'scene.usda')];scene.SetDefaultPrim(scene.GetPrimAtPath('/World'));scene.GetRootLayer().Save();m=json.loads((source/'manifest.json').read_text());m.update(status='scene_ceiling128_diagnostic_pending',scene_position_iteration_bounds={'min':64,'max':128},native_robot_position_request_preserved=128);(out/'manifest.json').write_text(json.dumps(m,indent=2)+'\n');s=Usd.Stage.Open(str(out/'probe.usda'));assert s.GetPrimAtPath('/World/WaterbathFluid/SampleSystem').GetAttribute('solverPositionIterationCount').Get()==128;assert s.GetPrimAtPath('/World/WaterbathFluid/BathSystem').GetAttribute('solverPositionIterationCount').Get()==64
    r={'source_package':str(source),'scope':'Scene maximum64->128 while minimum64 unchanged. Sample request128 and original native robot request128 are both allowed by the raised ceiling; not a Sample-only experiment. No executed iteration-loop count claim.','USD_actor_layers_unchanged':True,'probe_scene_min':64,'probe_scene_max':128,'Sample_request':128,'Bath_request':64,'native_robot_request':128,'native_yaml_required_changes':['generation_config.physics_scene_config.MaxPositionIterationCount:128','evaluation_configs[*].physics_scene_config.MaxPositionIterationCount:128'],'unchanged_native_settings':{'MinPositionIterationCount':64,'TimeStepsPerSecond':120,'dt':1/120,'num_steps':7000},'probe_sha256':hashlib.sha256((out/'probe.usda').read_bytes()).hexdigest(),'source_probe_sha256':hashlib.sha256((source/'probe.usda').read_bytes()).hexdigest(),'script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'qualified':False};(out/'receipt.json').write_text(json.dumps(r,indent=2)+'\n');return r
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--source',required=True);p.add_argument('--out',required=True);a=p.parse_args();print(json.dumps(build(a.source,a.out),indent=2))
